/**
 * Generated byte fixtures for unit tests only. Never imported by product code.
 */
import { createHash } from "node:crypto";
import { crc32, deflateRawSync } from "node:zlib";
import type { Source, SourceSelection, ValidatedUpload } from "@/contracts";
import { newId } from "@/contracts";

export function asSource(v: ValidatedUpload): Source {
  return { ...v, id: newId("src"), createdAt: new Date().toISOString() };
}

export function withIds<T extends object>(resolved: T): SourceSelection {
  return { ...resolved, id: newId("sel"), createdAt: new Date().toISOString() } as unknown as SourceSelection;
}

export const enc = (s: string) => new TextEncoder().encode(s);

// ---------------------------------------------------------------------------
// ZIP writer (for OOXML package tests)
// ---------------------------------------------------------------------------

export function makeZip(entries: Array<{ name: string; data: Uint8Array | string; deflate?: boolean; encryptedFlag?: boolean }>): Uint8Array {
  const parts: Buffer[] = [];
  const central: Buffer[] = [];
  let offset = 0;
  for (const e of entries) {
    const data = Buffer.from(typeof e.data === "string" ? enc(e.data) : e.data);
    const comp = e.deflate === false ? data : deflateRawSync(data);
    const method = e.deflate === false ? 0 : 8;
    const name = Buffer.from(e.name, "utf8");
    const crc = crc32(data);
    const flags = e.encryptedFlag ? 1 : 0;
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(flags, 6);
    local.writeUInt16LE(method, 8);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(comp.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    parts.push(local, name, comp);
    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0);
    cd.writeUInt16LE(20, 4);
    cd.writeUInt16LE(20, 6);
    cd.writeUInt16LE(flags, 8);
    cd.writeUInt16LE(method, 10);
    cd.writeUInt32LE(crc, 16);
    cd.writeUInt32LE(comp.length, 20);
    cd.writeUInt32LE(data.length, 24);
    cd.writeUInt16LE(name.length, 28);
    cd.writeUInt32LE(offset, 42);
    central.push(cd, name);
    offset += 30 + name.length + comp.length;
  }
  const cdBuf = Buffer.concat(central);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdBuf.length, 12);
  eocd.writeUInt32LE(offset, 16);
  return new Uint8Array(Buffer.concat([...parts, cdBuf, eocd]));
}

/** Rewrites one entry of an existing ZIP (used to tamper with an exceljs-written workbook). */
export async function rezip(
  bytes: Uint8Array,
  edit: (entries: Map<string, Uint8Array>) => void,
): Promise<Uint8Array> {
  const { readZipDirectory, readZipEntry } = await import("@/server/sources/zip");
  const map = new Map<string, Uint8Array>();
  for (const e of readZipDirectory(bytes)) map.set(e.name, readZipEntry(bytes, e, 50 * 1024 * 1024));
  edit(map);
  return makeZip([...map].map(([name, data]) => ({ name, data })));
}

// ---------------------------------------------------------------------------
// PDF writer
// ---------------------------------------------------------------------------

export interface PdfPageSpec {
  mediaBox: [number, number, number, number];
  rotate?: number;
  /** Raw content stream operators. */
  content: string;
}

export function makePdf(pages: PdfPageSpec[], options: { encrypt?: { userPassword: string; ownerPassword: string } } = {}): Uint8Array {
  const objects: string[] = [];
  // 1: catalog, 2: pages, then page/content pairs.
  const pageIds: number[] = [];
  const bodies: Array<{ id: number; body: string }> = [];
  let next = 3;
  for (const p of pages) {
    const pageId = next++;
    const contentId = next++;
    pageIds.push(pageId);
    bodies.push({
      id: pageId,
      body: `<< /Type /Page /Parent 2 0 R /MediaBox [${p.mediaBox.join(" ")}]${p.rotate ? ` /Rotate ${p.rotate}` : ""} /Contents ${contentId} 0 R /Resources << >> >>`,
    });
    bodies.push({ id: contentId, body: `<< /Length ${p.content.length} >>\nstream\n${p.content}\nendstream` });
  }
  objects[1] = "<< /Type /Catalog /Pages 2 0 R >>";
  objects[2] = `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pages.length} >>`;
  for (const b of bodies) objects[b.id] = b.body;

  const fileId = createHash("md5").update("unspin-test").digest();
  let trailerExtra = "";
  if (options.encrypt) {
    const encId = next++;
    const { O, U } = standardSecurityR2(options.encrypt.userPassword, options.encrypt.ownerPassword, -44, fileId);
    objects[encId] = `<< /Filter /Standard /V 1 /R 2 /Length 40 /P -44 /O <${O.toString("hex")}> /U <${U.toString("hex")}> >>`;
    trailerExtra = ` /Encrypt ${encId} 0 R`;
  }
  let out = "%PDF-1.4\n";
  const offsets: number[] = [];
  for (let i = 1; i < objects.length; i++) {
    offsets[i] = Buffer.byteLength(out, "latin1");
    out += `${i} 0 obj\n${objects[i]}\nendobj\n`;
  }
  const xref = Buffer.byteLength(out, "latin1");
  out += `xref\n0 ${objects.length}\n0000000000 65535 f \n`;
  for (let i = 1; i < objects.length; i++) out += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
  out += `trailer\n<< /Size ${objects.length} /Root 1 0 R /ID [<${fileId.toString("hex")}> <${fileId.toString("hex")}>]${trailerExtra} >>\nstartxref\n${xref}\n%%EOF\n`;
  return new Uint8Array(Buffer.from(out, "latin1"));
}

const PAD = Buffer.from("28BF4E5E4E758A4164004E56FFFA01082E2E00B6D0683E802F0CA9FE6453697A", "hex");

function rc4(key: Buffer, data: Buffer): Buffer {
  const s = Array.from({ length: 256 }, (_, i) => i);
  let j = 0;
  for (let i = 0; i < 256; i++) {
    j = (j + s[i] + key[i % key.length]) & 255;
    [s[i], s[j]] = [s[j], s[i]];
  }
  const out = Buffer.alloc(data.length);
  let i = 0;
  j = 0;
  for (let k = 0; k < data.length; k++) {
    i = (i + 1) & 255;
    j = (j + s[i]) & 255;
    [s[i], s[j]] = [s[j], s[i]];
    out[k] = data[k] ^ s[(s[i] + s[j]) & 255];
  }
  return out;
}

function padPw(pw: string): Buffer {
  return Buffer.concat([Buffer.from(pw, "latin1"), PAD]).subarray(0, 32);
}

/** PDF Standard Security Handler revision 2 (40-bit RC4), algorithms 3.2–3.4 of PDF 1.7. */
function standardSecurityR2(user: string, owner: string, p: number, fileId: Buffer): { O: Buffer; U: Buffer } {
  const ownerKey = createHash("md5").update(padPw(owner)).digest().subarray(0, 5);
  const O = rc4(ownerKey, padPw(user));
  const pBuf = Buffer.alloc(4);
  pBuf.writeInt32LE(p, 0);
  const fileKey = createHash("md5").update(Buffer.concat([padPw(user), O, pBuf, fileId])).digest().subarray(0, 5);
  const U = rc4(fileKey, PAD);
  return { O, U };
}

// ---------------------------------------------------------------------------
// PNG header with arbitrary claimed dimensions (for pixel-limit tests)
// ---------------------------------------------------------------------------

export function pngHeaderOnly(width: number, height: number): Uint8Array {
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const chunk = (type: string, data: Buffer) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length, 0);
    const td = Buffer.concat([Buffer.from(type, "latin1"), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(td), 0);
    return Buffer.concat([len, td, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 0;
  return new Uint8Array(Buffer.concat([sig, chunk("IHDR", ihdr), chunk("IDAT", deflateRawSync(Buffer.alloc(0))), chunk("IEND", Buffer.alloc(0))]));
}
